const p = $input.first().json || {};
const isBlank = (v) => v === undefined || v === null || String(v).trim() === '';
const toText = (v) => isBlank(v) ? null : String(v).trim();
const priority = ['os_codigo', 'os_id_bomsaldo', 'conversa_id', 'tecnico_id'];
let busca_por = null;
let campo_busca = null;
let valor_busca = null;
for (const campo of priority) {
  if (!isBlank(p[campo])) {
    busca_por = campo;
    campo_busca = campo;
    valor_busca = toText(p[campo]);
    break;
  }
}
if (!busca_por) {
  throw new Error('os_codigo, os_id_bomsaldo, conversa_id ou tecnico_id e obrigatorio para buscar contexto.');
}
return [{ json: {
  os_codigo: toText(p.os_codigo),
  os_id_bomsaldo: toText(p.os_id_bomsaldo),
  conversa_id: toText(p.conversa_id),
  tecnico_id: toText(p.tecnico_id),
  busca_por,
  campo_busca,
  valor_busca
}}];

const p = $('Validar Params').first().json || {};
const items = $input.all().map(i => i.json || {}).filter(r => r && r.os_codigo);
const isActive = (s) => ['aberta', 'em_andamento'].includes(String(s || '').trim().toLowerCase());
const parseJson = (val) => {
  if (val === undefined || val === null || val === '') return [];
  if (Array.isArray(val)) return val;
  if (typeof val === 'string') {
    try {
      const parsed = JSON.parse(val);
      return Array.isArray(parsed) ? parsed : [];
    } catch {}
  }
  return [];
};
let os = null;
if (p.busca_por === 'tecnico_id') {
  os = items.find(r => isActive(r.status_os)) || items[0] || null;
} else {
  os = items[0] || null;
}
if (!os) {
  return [{ json: {
    encontrado: false,
    busca_por: p.busca_por,
    os_codigo: p.os_codigo || null,
    os_id_bomsaldo: p.os_id_bomsaldo || null,
    conversa_id: p.conversa_id || null,
    tecnico_id: p.tecnico_id || null,
    mensagem: 'Nenhuma OS encontrada com os criterios informados.',
    contexto: null,
    produtos: [],
    servicos: [],
    pendencias: ['OS nao encontrada'],
    pronto_para_fechar: false,
    resumo: 'Nenhuma OS foi localizada.'
  }}];
}
const produtos = parseJson(os.produtos_json);
const servicos = parseJson(os.servicos_json);
const pendencias = [];
if (!os.cliente_codigo) pendencias.push('Cliente sem codigo oficial');
if (!os.defeito) pendencias.push('Defeito nao informado');
if (!os.solucao) pendencias.push('Solucao nao informada');
if (!os.em_garantia && !os.tipo_pagamento) pendencias.push('Forma de pagamento nao definida');
const resumo = [
  `OS #${os.os_codigo}`,
  `Cliente: ${os.cliente_nome || 'nao identificado'} (cod: ${os.cliente_codigo || 'pendente'})`,
  `Tecnico: ${os.tecnico_nome || 'nao identificado'}`,
  `Status: ${os.status_os} | Fase: ${os.fase_ia}`,
  `Defeito: ${os.defeito || 'nao informado'}`,
  `Causa: ${os.causa || 'nao informada'}`,
  `Solucao: ${os.solucao || 'nao informada'}`,
  `Garantia: ${os.em_garantia ? 'SIM' : 'NAO'}`,
  `Pagamento: ${os.tipo_pagamento || 'nao definido'}`,
  `Entrada: ${os.hora_entrada || 'nao registrada'}`,
  `Saida: ${os.hora_saida || 'nao registrada'}`,
  `Evidencias: ${os.qtd_evidencias || 0}`,
  `Produtos: ${produtos.length}`,
  `Servicos: ${servicos.length}`
].join('\n');
return [{ json: {
  encontrado: true,
  busca_por: p.busca_por,
  os_codigo: os.os_codigo,
  os_id_bomsaldo: os.os_id_bomsaldo || null,
  conversa_id: os.conversa_id || null,
  tecnico_id: os.tecnico_id || null,
  tecnico_nome: os.tecnico_nome || null,
  tecnico_whatsapp: os.tecnico_whatsapp || null,
  cliente_nome: os.cliente_nome || null,
  cliente_codigo: os.cliente_codigo || null,
  cliente_endereco: os.cliente_endereco || null,
  equipamento: os.equipamento || null,
  equipamento_codigo: os.equipamento_codigo || null,
  marca: os.marca || null,
  modelo: os.modelo || null,
  defeito: os.defeito || null,
  causa: os.causa || null,
  solucao: os.solucao || null,
  relatorio_tecnico: os.relatorio_tecnico || null,
  tipo_servico: os.tipo_servico || null,
  servico_nome: os.servico_nome || null,
  servico_codigo: os.servico_codigo || null,
  observacoes_orientacao: os.observacoes_orientacao || null,
  em_garantia: os.em_garantia || false,
  tipo_pagamento: os.tipo_pagamento || null,
  forma_pagamento_id: os.forma_pagamento_id || null,
  valor_total: os.valor_total || 0,
  hora_entrada: os.hora_entrada || null,
  hora_saida: os.hora_saida || null,
  checkin_registrado: os.checkin_registrado || false,
  checkout_registrado: os.checkout_registrado || false,
  link_pasta_drive: os.link_pasta_drive || null,
  qtd_evidencias: os.qtd_evidencias || 0,
  status_os: os.status_os || null,
  fase_ia: os.fase_ia || null,
  motivo_cancelamento: os.motivo_cancelamento || null,
  tempo_atendimento_min: os.tempo_atendimento_min || null,
  produtos_json_raw: os.produtos_json || null,
  servicos_json_raw: os.servicos_json || null,
  produtos,
  servicos,
  contexto: os,
  pendencias,
  pronto_para_fechar: pendencias.length === 0,
  resumo
}}];

const base = $('Selecionar OS').first().json || {};
const evidencias = $input.all().map(i => i.json || {}).filter(e => e && (e.id || e.url_origem || e.link_arquivo || e.descricao));
const isBlank = (v) => v === undefined || v === null || String(v).trim() === '';
const parseJson = (val) => {
  if (val === undefined || val === null || val === '') return [];
  if (Array.isArray(val)) return val;
  if (typeof val === 'string') {
    try {
      const parsed = JSON.parse(val);
      return Array.isArray(parsed) ? parsed : [];
    } catch {}
  }
  return [];
};

if (!base.encontrado) {
  return [{ json: {
    encontrado: false,
    busca_por: base.busca_por || $('Validar Params').first().json.busca_por,
    os_codigo: base.os_codigo || null,
    os_id_bomsaldo: base.os_id_bomsaldo || null,
    conversa_id: base.conversa_id || null,
    tecnico_id: base.tecnico_id || null,
    mensagem: base.mensagem || 'Nenhuma OS encontrada.',
    contexto: null,
    produtos: [],
    servicos: [],
    evidencias: []
  }}];
}

const contexto = { ...(base.contexto || {}) , evidencias };
const produtos = base.produtos || parseJson(base.produtos_json_raw);
const servicos = base.servicos || parseJson(base.servicos_json_raw);
const pendencias = Array.isArray(base.pendencias) ? [...base.pendencias] : [];
if (evidencias.length === 0) pendencias.push('Sem evidencias registradas');

const resumo = [
  `OS #${base.os_codigo}`,
  `Cliente: ${base.cliente_nome || 'nao identificado'} (cod: ${base.cliente_codigo || 'pendente'})`,
  `Tecnico: ${base.tecnico_nome || 'nao identificado'}`,
  `Status: ${base.status_os || 'nao informado'} | Fase: ${base.fase_ia || 'nao informada'}`,
  `Defeito: ${base.defeito || 'nao informado'}`,
  `Causa: ${base.causa || 'nao informada'}`,
  `Solucao: ${base.solucao || 'nao informada'}`,
  `Garantia: ${base.em_garantia ? 'SIM' : 'NAO'}`,
  `Pagamento: ${base.tipo_pagamento || 'nao definido'}`,
  `Entrada: ${base.hora_entrada || 'nao registrada'}`,
  `Saida: ${base.hora_saida || 'nao registrada'}`,
  `Evidencias: ${evidencias.length}`,
  `Produtos: ${produtos.length}`,
  `Servicos: ${servicos.length}`
].join('\n');

return [{ json: {
  encontrado: true,
  busca_por: base.busca_por,
  os_codigo: base.os_codigo,
  os_id_bomsaldo: base.os_id_bomsaldo || null,
  conversa_id: base.conversa_id || null,
  tecnico_id: base.tecnico_id || null,
  tecnico_nome: base.tecnico_nome || null,
  tecnico_whatsapp: base.tecnico_whatsapp || null,
  cliente_nome: base.cliente_nome || null,
  cliente_codigo: base.cliente_codigo || null,
  cliente_endereco: base.cliente_endereco || null,
  equipamento: base.equipamento || null,
  equipamento_codigo: base.equipamento_codigo || null,
  marca: base.marca || null,
  modelo: base.modelo || null,
  defeito: base.defeito || null,
  causa: base.causa || null,
  solucao: base.solucao || null,
  relatorio_tecnico: base.relatorio_tecnico || null,
  tipo_servico: base.tipo_servico || null,
  servico_nome: base.servico_nome || null,
  servico_codigo: base.servico_codigo || null,
  observacoes_orientacao: base.observacoes_orientacao || null,
  em_garantia: base.em_garantia || false,
  tipo_pagamento: base.tipo_pagamento || null,
  forma_pagamento_id: base.forma_pagamento_id || null,
  valor_total: base.valor_total || 0,
  hora_entrada: base.hora_entrada || null,
  hora_saida: base.hora_saida || null,
  checkin_registrado: base.checkin_registrado || false,
  checkout_registrado: base.checkout_registrado || false,
  link_pasta_drive: base.link_pasta_drive || null,
  qtd_evidencias: base.qtd_evidencias || 0,
  status_os: base.status_os || null,
  fase_ia: base.fase_ia || null,
  motivo_cancelamento: base.motivo_cancelamento || null,
  tempo_atendimento_min: base.tempo_atendimento_min || null,
  produtos_json_raw: base.produtos_json_raw || null,
  servicos_json_raw: base.servicos_json_raw || null,
  produtos,
  servicos,
  evidencias,
  contexto,
  pendencias,
  pronto_para_fechar: pendencias.length === 0,
  resumo
}}];

const p = $input.first().json;

if (!p.os_codigo && !p.tecnico_id) {
  throw new Error('os_codigo OU tecnico_id é obrigatório para buscar contexto.');
}

return [{ json: {
  os_codigo: p.os_codigo ? String(p.os_codigo) : null,
  tecnico_id: p.tecnico_id ? String(p.tecnico_id) : null,
  busca_por: p.os_codigo ? 'os_codigo' : 'tecnico_id'
}}];

const os = $input.first().json;
const p = $('Validar Params').first().json;

// Se não encontrou (item vazio do alwaysOutputData)
if (!os || !os.os_codigo) {
  return [{ json: {
    encontrado: false,
    os_codigo: p.os_codigo || null,
    tecnico_id: p.tecnico_id || null,
    mensagem: p.os_codigo
      ? `Nenhuma OS encontrada com código ${p.os_codigo}.`
      : `Nenhuma OS ativa encontrada para o técnico.`,
    contexto: null,
    produtos: [],
    servicos: []
  }}];
}

// Parsear produtos e serviços do JSONB
let produtos = [];
let servicos = [];
try { produtos = typeof os.produtos_json === 'string' ? JSON.parse(os.produtos_json) : (os.produtos_json || []); } catch(e) {}
try { servicos = typeof os.servicos_json === 'string' ? JSON.parse(os.servicos_json) : (os.servicos_json || []); } catch(e) {}

// Verificar se está pronto para fechar
const problemas = [];
if (!os.cliente_codigo) problemas.push('Cliente sem código oficial');
if (!os.defeito) problemas.push('Defeito não informado');
if (!os.solucao) problemas.push('Solução não informada');
if (!os.tipo_pagamento && !os.em_garantia) problemas.push('Forma de pagamento não definida');

const resumo = [
  `OS #${os.os_codigo}`,
  `Cliente: ${os.cliente_nome || 'não identificado'} (cód: ${os.cliente_codigo || 'pendente'})`,
  `Técnico: ${os.tecnico_nome || 'não identificado'}`,
  `Status: ${os.status_os} | Fase: ${os.fase_ia}`,
  `Defeito: ${os.defeito || 'não informado'}`,
  `Causa: ${os.causa || 'não informada'}`,
  `Solução: ${os.solucao || 'não informada'}`,
  `Garantia: ${os.em_garantia ? 'SIM' : 'NÃO'}`,
  `Pagamento: ${os.tipo_pagamento || 'não definido'}`,
  `Entrada: ${os.hora_entrada || 'não registrada'}`,
  `Saída: ${os.hora_saida || 'não registrada'}`,
  `Evidências: ${os.qtd_evidencias || 0}`,
  `Produtos: ${produtos.length}`,
  `Serviços: ${servicos.length}`
].join('\n');

return [{ json: {
  encontrado: true,
  os_codigo: os.os_codigo,
  os_id_bomsaldo: os.os_id_bomsaldo,
  status_os: os.status_os,
  fase_ia: os.fase_ia,
  pronto_para_fechar: problemas.length === 0,
  problemas_encontrados: problemas,
  contexto: os,
  produtos,
  servicos,
  resumo
}}];
